const item = $input.first().json;
const body = item.body;

// Ignora eventos que não sejam mensagens recebidas do cliente (evita loop com as próprias respostas do bot)
if (body.message_type !== undefined && body.message_type !== 'incoming') {
  return [];
}
if (body.private === true) {
  return [];
}

const senderName = (body.sender && body.sender.name) ? body.sender.name : '';

const dados = {
  phone_raw: body.sender ? body.sender.phone_number : null,
  message: body.content,
  conversation_id: body.conversation.id,
  account_id: body.account.id,
  sender_name: senderName,
  first_name: senderName ? senderName.split(' ')[0] : null
};

return [{ json: dados }];

const input = $input.first().json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.estadosConversa) staticData.estadosConversa = {};
if (!staticData.dadosColeta) staticData.dadosColeta = {};

const estadoAtual = staticData.estadosConversa[input.conversation_id];
const mensagemOriginal = input.message || '';
const mensagem = mensagemOriginal
  .toLowerCase()
  .normalize('NFD')
  .replace(/[̀-ͯ]/g, '')
  .trim();

if (!staticData.dadosColeta[input.conversation_id]) staticData.dadosColeta[input.conversation_id] = {};
const dados = staticData.dadosColeta[input.conversation_id];

// Persona Cecília — variação de saudação (evita soar repetitivo/robótico)
const SAUDACOES_EXTRAS = [
  '! Tudo bem?',
  '! Como você tá?',
  '! Espero que esteja tudo ótimo',
  '! Que bom falar com você',
  '! Tudo certo?'
];
function escolherAleatorio(lista) {
  return lista[Math.floor(Math.random() * lista.length)];
}

function gerarId() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

function saudacaoPorHorario() {
  const agora = new Date();
  const horaRecife = new Date(agora.toLocaleString('en-US', { timeZone: 'America/Recife' }));
  const hora = horaRecife.getHours();
  if (hora >= 5 && hora < 12) return { texto: 'Bom dia', emoji: '☀️' };
  if (hora >= 12 && hora < 18) return { texto: 'Boa tarde', emoji: '🌤️' };
  return { texto: 'Boa noite', emoji: '🌙' };
}

function dentroDoHorarioComercial() {
  const agora = new Date();
  const horaRecife = new Date(agora.toLocaleString('en-US', { timeZone: 'America/Recife' }));
  const hora = horaRecife.getHours();
  return hora >= 8 && hora < 20;
}

function pushPergunta(intro, opcoesTexto) {
  mensagens.push({ texto: intro, espera: 3 });
  mensagens.push({ texto: '*Digite*', espera: 2 });
  mensagens.push({ texto: opcoesTexto, espera: 5 });
}

const OPCOES_JA_TEM_RESERVA = '1️⃣ Sim, já tenho uma reserva\n2️⃣ Não tenho reserva';
const OPCOES_MENU_SEM_RESERVA = '1️⃣ Consultar disponibilidade\n2️⃣ Fazer nova reserva\n3️⃣ Tirar dúvida\n4️⃣ Falar com atendente';
const OPCOES_QUARTOS = '1️⃣ 1 quarto\n2️⃣ 2 quartos';
const OPCOES_ESTACIONAMENTO = '1️⃣ Sim\n2️⃣ Não';
const OPCOES_CAUCAO = '1️⃣ Gerar link de pagamento\n2️⃣ Tirar dúvida\n3️⃣ Falar com atendente\n4️⃣ Voltar';
const EMOJI_NUMEROS_MOTOR = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣'];

let mensagens = [];
let novoEstado = estadoAtual;
let precisaConsultarReserva = false;
let codigoReserva = null;
let precisaCriarCheckoutCaucao = false;
let securityDepositId = null;

if (!estadoAtual) {
  const nome = input.first_name ? `, ${input.first_name}` : '';
  const { texto: saudacao, emoji } = saudacaoPorHorario();

  mensagens.push({ texto: 'Oi! 👋', espera: 20 });
  mensagens.push({ texto: `${saudacao}${nome}${escolherAleatorio(SAUDACOES_EXTRAS)} ${emoji}`, espera: 20 });

  if (dentroDoHorarioComercial()) {
    pushPergunta('Você já tem reserva com a gente?', OPCOES_JA_TEM_RESERVA);
    novoEstado = 'aguardando_confirmacao_reserva';
  } else {
    mensagens.push({ texto: 'Que pena, você escreveu fora do nosso horário! 🌙', espera: 5 });
    mensagens.push({ texto: 'Nosso atendimento é das 8h às 20h — mas pode me contar o que você precisa que, assim que a equipe voltar, já vê tudinho! 🙏', espera: 5 });
    novoEstado = 'fora_horario';
  }

} else if (estadoAtual === 'fora_horario') {
  if (dentroDoHorarioComercial()) {
    mensagens.push({ texto: 'Boa notícia, já voltamos! ☀️', espera: 5 });
    pushPergunta('Você já tem reserva com a gente?', OPCOES_JA_TEM_RESERVA);
    novoEstado = 'aguardando_confirmacao_reserva';
  } else {
    mensagens.push({ texto: 'Recebi sua mensagem, viu? 😊', espera: 5 });
    mensagens.push({ texto: 'Nosso horário é das 8h às 20h — assim que abrir, a equipe já te responde, tá bom? 🙏', espera: 5 });
    novoEstado = 'fora_horario';
  }

} else if (estadoAtual === 'aguardando_confirmacao_reserva') {
  const confirmaNao = /\b(2|nao)\b/.test(mensagem);
  const confirmaSim = !confirmaNao && /\b(1|sim|tenho|ja)\b/.test(mensagem);

  if (confirmaSim) {
    mensagens.push({ texto: 'Show! Já vou te conectar com a equipe, só um minutinho! 😊', espera: 30 });
    mensagens.push({ texto: 'Me passa o número da sua reserva?', espera: 40 });
    novoEstado = 'aguardando_numero_reserva';
  } else if (confirmaNao) {
    mensagens.push({ texto: 'Entendi! 😊 O que você gostaria de fazer?', espera: 5 });
    pushPergunta('Escolhe uma dessas pra mim:', OPCOES_MENU_SEM_RESERVA);
    novoEstado = 'aguardando_opcao_sem_reserva';
  } else {
    mensagens.push({ texto: 'Ih, não entendi direito 😅', espera: 5 });
    pushPergunta('Você já tem reserva com a gente?', OPCOES_JA_TEM_RESERVA);
    novoEstado = 'aguardando_confirmacao_reserva';
  }

} else if (estadoAtual === 'aguardando_numero_reserva') {
  precisaConsultarReserva = true;
  codigoReserva = mensagemOriginal
    .trim()
    .toUpperCase()
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '');
  novoEstado = 'consultando_reserva';

} else if (estadoAtual === 'aguardando_nome_reserva') {
  mensagens.push({ texto: 'Hmm, não consegui localizar sua reserva no sistema 🤔', espera: 5 });
  mensagens.push({ texto: 'Vou te conectar com a equipe, só um minutinho…', espera: 5 });
  novoEstado = 'transferido_humano';

} else if (estadoAtual === 'aguardando_opcao_sem_reserva') {
  const opcao = mensagem;

  if (opcao.startsWith('1')) {
    mensagens.push({ texto: 'Perfeito! 🏖️ Temos unidades em Boa Viagem e no Pina.', espera: 5 });
    mensagens.push({ texto: 'Pra te ajudar melhor, me conta: para quantas pessoas seria a hospedagem?', espera: 5 });
    novoEstado = 'disp_pessoas';
  } else if (opcao.startsWith('2')) {
    mensagens.push({ texto: 'Legal! Vamos começar sua reserva. 🎉', espera: 5 });
    mensagens.push({ texto: 'Qual seu nome completo?', espera: 5 });
    novoEstado = 'reserva_nome';
  } else if (opcao.startsWith('3')) {
    mensagens.push({ texto: 'Pode me contar sua dúvida que já registro pra equipe te responder. 😊', espera: 5 });
    novoEstado = 'coletando_duvida';
  } else if (opcao.startsWith('4')) {
    mensagens.push({ texto: 'Certo! Já vou te conectar com a equipe, só um minutinho…', espera: 5 });
    novoEstado = 'transferido_humano';
  } else {
    mensagens.push({ texto: 'Ih, não entendi direito 😅', espera: 5 });
    pushPergunta('Escolhe uma dessas pra mim:', OPCOES_MENU_SEM_RESERVA);
    novoEstado = 'aguardando_opcao_sem_reserva';
  }

} else if (estadoAtual === 'disp_pessoas') {
  dados.pessoas = mensagemOriginal.trim();
  mensagens.push({ texto: 'Show! 🙂', espera: 5 });
  mensagens.push({ texto: 'E quando você gostaria de fazer o check-in?', espera: 5 });
  novoEstado = 'disp_checkin';

} else if (estadoAtual === 'disp_checkin') {
  dados.checkin = mensagemOriginal.trim();
  pushPergunta('Você tem preferência por um apartamento de 1 ou 2 quartos?', OPCOES_QUARTOS);
  novoEstado = 'disp_quartos';

} else if (estadoAtual === 'disp_quartos') {
  dados.quartos = mensagemOriginal.trim();
  pushPergunta('Precisa de vaga de estacionamento?', OPCOES_ESTACIONAMENTO);
  novoEstado = 'disp_estacionamento';

} else if (estadoAtual === 'disp_estacionamento') {
  dados.estacionamento = mensagemOriginal.trim();
  const resumo = `📋 Resumo (consulta de disponibilidade):\n- Pessoas: ${dados.pessoas}\n- Check-in desejado: ${dados.checkin}\n- Quartos: ${dados.quartos}\n- Estacionamento: ${dados.estacionamento}`;
  mensagens.push({ texto: resumo, espera: 2, privado: true });
  mensagens.push({ texto: 'Anotadinho! 📝', espera: 5 });
  mensagens.push({ texto: 'Vou te conectar com a equipe agora, eles já têm tudo que você me contou! 😊', espera: 5 });
  novoEstado = 'transferido_humano';

} else if (estadoAtual === 'reserva_nome') {
  dados.nome = mensagemOriginal.trim();
  mensagens.push({ texto: 'Prazer! 😊', espera: 5 });
  mensagens.push({ texto: 'Para quantas pessoas seria a reserva?', espera: 5 });
  novoEstado = 'reserva_pessoas';

} else if (estadoAtual === 'reserva_pessoas') {
  dados.pessoas = mensagemOriginal.trim();
  mensagens.push({ texto: 'Qual data você gostaria de fazer o check-in?', espera: 5 });
  novoEstado = 'reserva_checkin';

} else if (estadoAtual === 'reserva_checkin') {
  dados.checkin = mensagemOriginal.trim();
  mensagens.push({ texto: 'E o check-out, para quando seria?', espera: 5 });
  novoEstado = 'reserva_checkout';

} else if (estadoAtual === 'reserva_checkout') {
  dados.checkout = mensagemOriginal.trim();
  pushPergunta('Você tem preferência por um apartamento de 1 ou 2 quartos?', OPCOES_QUARTOS);
  novoEstado = 'reserva_quartos';

} else if (estadoAtual === 'reserva_quartos') {
  dados.quartos = mensagemOriginal.trim();
  pushPergunta('Precisa de vaga de estacionamento?', OPCOES_ESTACIONAMENTO);
  novoEstado = 'reserva_estacionamento';

} else if (estadoAtual === 'reserva_estacionamento') {
  dados.estacionamento = mensagemOriginal.trim();
  const resumo = `📋 Resumo (nova reserva):\n- Nome: ${dados.nome}\n- Pessoas: ${dados.pessoas}\n- Check-in: ${dados.checkin}\n- Check-out: ${dados.checkout}\n- Quartos: ${dados.quartos}\n- Estacionamento: ${dados.estacionamento}`;
  mensagens.push({ texto: resumo, espera: 2, privado: true });
  mensagens.push({ texto: 'Perfeito! 🎉', espera: 5 });
  mensagens.push({ texto: 'Vou te conectar com a equipe agora, eles já têm tudo que você me contou! 😊', espera: 5 });
  novoEstado = 'transferido_humano';

} else if (estadoAtual === 'coletando_duvida') {
  mensagens.push({ texto: 'Anotadinho! 📝', espera: 5 });
  mensagens.push({ texto: 'Vou te conectar com a equipe agora, eles já têm tudo que você me contou! 😊', espera: 5 });
  novoEstado = 'transferido_humano';

} else if (estadoAtual === 'aguardando_escolha_pendencia') {
  const escolhaIndex = parseInt(mensagemOriginal.trim(), 10) - 1;
  const opcoes = dados.pendenciasAplicaveis || [];
  const escolhida = opcoes[escolhaIndex];
  dados.pendenciaEscolhida = escolhida ? escolhida.chave : mensagemOriginal.trim();

  if (dados.pendenciaEscolhida === 'caucao') {
    const valor = dados.caucaoValor ? Number(dados.caucaoValor).toFixed(2).replace('.', ',') : null;
    mensagens.push({ texto: valor ? `A caução reembolsável da sua reserva é de R$ ${valor}.` : 'Sobre a caução reembolsável da sua reserva:', espera: 3 });
    mensagens.push({ texto: 'Essa informação faz parte dos termos da sua reserva — dá pra conferir também direto na plataforma que você reservou (Booking, Airbnb etc.), na parte de políticas da propriedade.', espera: 5 });
    mensagens.push({ texto: 'É um valor de garantia, devolvido depois do check-out se estiver tudo certo com o apartamento.', espera: 4 });
    pushPergunta('O que você gostaria de fazer?', OPCOES_CAUCAO);
    novoEstado = 'caucao_info';
  } else {
    mensagens.push({ texto: 'Já vou te conectar com a equipe, só um minutinho! 😊', espera: 5 });
    novoEstado = 'transferido_humano';
  }

} else if (estadoAtual === 'caucao_info') {
  const pedeVoltar = mensagem.startsWith('4') || /voltar/.test(mensagem);
  const pedeAtendente = mensagem.startsWith('3') || /atendente|humano|colaborador|pessoa real|falar com/.test(mensagem);
  const pedeLink = mensagem.startsWith('1') || /gerar|link|pagar|pagamento|pix/.test(mensagem);
  const pedeDuvida = mensagem.startsWith('2') || /duvida|saber mais|explica|entend/.test(mensagem);
  const objecao = /nao sabia|nunca vi|nao vi isso|nao tinha isso|nao esta na reserva|nao tem isso|cade isso|nao concordo|enganacao|golpe|cobranca indevida|isso e um absurdo/.test(mensagem);

  if (pedeVoltar) {
    const opcoes = dados.pendenciasAplicaveis || [];
    if (opcoes.length > 0) {
      mensagens.push({ texto: 'Voltando! Essas são as pendências:', espera: 3 });
      mensagens.push({ texto: '*Digite*', espera: 2 });
      const lista = opcoes.map((p, i) => `${EMOJI_NUMEROS_MOTOR[i] || (i + 1) + '.'} ${p.label}`).join('\n');
      mensagens.push({ texto: lista, espera: 5 });
      novoEstado = 'aguardando_escolha_pendencia';
    } else {
      mensagens.push({ texto: 'Já vou te conectar com a equipe, só um minutinho! 😊', espera: 5 });
      novoEstado = 'transferido_humano';
    }
  } else if (pedeAtendente) {
    mensagens.push({ texto: 'Já vou te conectar com a equipe, só um minutinho! 😊', espera: 5 });
    novoEstado = 'transferido_humano';
  } else if (pedeLink) {
    precisaCriarCheckoutCaucao = true;
    securityDepositId = gerarId();
    novoEstado = 'criando_checkout_caucao';
  } else if (pedeDuvida || objecao) {
    if (objecao) {
      mensagens.push({ texto: 'Entendo a dúvida! Mas pode ficar tranquilo(a), não é nenhum engano 😊', espera: 3 });
    }
    mensagens.push({ texto: 'A caução é uma prática comum em temporada — funciona como uma garantia, e você recebe de volta depois do check-out se estiver tudo certo com o apartamento.', espera: 4 });
    mensagens.push({ texto: 'Essa condição está nos termos da sua reserva, incluindo na plataforma onde você reservou (Booking, Airbnb etc.) — pode conferir por lá também.', espera: 4 });
    pushPergunta('O que você gostaria de fazer?', OPCOES_CAUCAO);
    novoEstado = 'caucao_info';
  } else {
    mensagens.push({ texto: 'Desculpa, não entendi 😅', espera: 3 });
    pushPergunta('O que você gostaria de fazer?', OPCOES_CAUCAO);
    novoEstado = 'caucao_info';
  }

} else {
  mensagens = [];
  novoEstado = estadoAtual;
}

staticData.estadosConversa[input.conversation_id] = novoEstado;

return [{
  json: {
    ...input,
    ...dados,
    mensagens,
    precisaConsultarReserva,
    codigoReserva,
    precisaCriarCheckoutCaucao,
    securityDepositId,
    estado: novoEstado
  }
}];

const resultado = $input.first().json;
const contexto = $('Motor de Estado').first().json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.estadosConversa) staticData.estadosConversa = {};
if (!staticData.dadosColeta) staticData.dadosColeta = {};
if (!staticData.dadosColeta[contexto.conversation_id]) staticData.dadosColeta[contexto.conversation_id] = {};
const dados = staticData.dadosColeta[contexto.conversation_id];

const EMOJI_NUMEROS = ['1️⃣', '2️⃣', '3️⃣', '4️⃣', '5️⃣'];

let mensagens = [];
let novoEstado;

const encontrou = Boolean(resultado && resultado.booking_code);

if (encontrou) {
  const nome = resultado.guest_name || contexto.sender_name || 'hóspede';
  const quartos = resultado.bedrooms;
  const bairro = resultado.neighborhood;
  const temCaucao = resultado.default_deposit_amount && Number(resultado.default_deposit_amount) > 0;

  const pendenciasAplicaveis = [];
  if (temCaucao && !resultado.comprovante_ok) {
    pendenciasAplicaveis.push({ chave: 'caucao', label: 'Caução Reembolsável' });
  }
  if (!resultado.doc_ok) {
    pendenciasAplicaveis.push({ chave: 'documentacao', label: 'Envio da documentação dos hóspedes' });
  }
  if (!resultado.fnrh_ok || !resultado.form_ok) {
    pendenciasAplicaveis.push({ chave: 'fnrh', label: 'Preenchimento da ficha FNRH' });
  }

  dados.pendenciasAplicaveis = pendenciasAplicaveis;
  dados.propertyId = resultado.propertyId;
  dados.bookingId = resultado.booking_id;
  dados.bookingCode = resultado.booking_code;
  dados.caucaoValor = (resultado.booking_code || '').toUpperCase().startsWith('TESTE')
    ? '1.00' // valor reduzido só para reservas de teste (booking_code TESTE-*), não afeta reservas reais
    : resultado.default_deposit_amount;
  dados.guestName = nome;

  mensagens.push({ texto: 'Aguarde um minuto, enquanto localizo sua reserva 🔎', espera: 5 });
  mensagens.push({ texto: 'Reserva Confirmada ✅', espera: 5 });
  mensagens.push({ texto: `Encontrei sua reserva, ${nome}!`, espera: 5 });
  mensagens.push({ texto: `Você reservou o Apartamento de ${quartos} quarto${quartos === 1 ? '' : 's'} em ${bairro}`, espera: 5 });
  mensagens.push({ texto: 'Vou verificar se há alguma pendência, ou se posso finalizar e confirmar sua reserva.', espera: 5 });

  if (pendenciasAplicaveis.length === 0) {
    mensagens.push({ texto: 'Está tudo certo com sua documentação e cadastro! ✅ Sua reserva está confirmada.', espera: 5 });
    novoEstado = 'atendimento_concluido';
  } else {
    const plural = pendenciasAplicaveis.length > 1 ? 's' : '';
    mensagens.push({ texto: `Temos ${pendenciasAplicaveis.length} pendência${plural} em seu cadastro antes de finalizarmos.`, espera: 3 });
    mensagens.push({ texto: 'Vou listar e você me fala por onde quer começar:', espera: 3 });
    mensagens.push({ texto: '*Digite*', espera: 2 });
    const lista = pendenciasAplicaveis.map((p, i) => `${EMOJI_NUMEROS[i] || (i + 1) + '.'} ${p.label}`).join('\n');
    mensagens.push({ texto: lista, espera: 5 });
    novoEstado = 'aguardando_escolha_pendencia';
  }
} else {
  mensagens.push({ texto: 'Não consegui localizar essa reserva no sistema.', espera: 5 });
  mensagens.push({ texto: 'Por favor, me informe em nome de quem está a reserva', espera: 5 });
  novoEstado = 'aguardando_nome_reserva';
}

staticData.estadosConversa[contexto.conversation_id] = novoEstado;

return [{
  json: {
    ...contexto,
    mensagens,
    estado: novoEstado
  }
}];

