const contexto = $('Motor de Estado').first().json;
const linkResp = $('InfinitePay - Criar Link').first().json;

const staticData = $getWorkflowStaticData('global');
if (!staticData.estadosConversa) staticData.estadosConversa = {};

const valor = contexto.caucaoValor ? Number(contexto.caucaoValor).toFixed(2).replace('.', ',') : null;

let mensagens = [];
mensagens.push({ texto: 'Show! 😊', espera: 3 });
mensagens.push({ texto: valor ? `Aqui está o link seguro pra pagar a caução (R$ ${valor}):` : 'Aqui está o link seguro pra pagar a caução:', espera: 3 });
mensagens.push({ texto: linkResp.url, espera: 5 });
mensagens.push({ texto: 'Assim que o pagamento cair, eu confirmo aqui automaticamente pra você ✅', espera: 4 });
mensagens.push({ texto: 'Qualquer coisa, é só chamar a gente!', espera: 4 });

const novoEstado = 'transferido_humano';
staticData.estadosConversa[contexto.conversation_id] = novoEstado;

return [{
  json: {
    ...contexto,
    mensagens,
    estado: novoEstado
  }
}];
